class F{String s(boolean p,String[]x){var a=new java.util.Scanner(p?x[0]:x[0].replace(" ","")).useDelimiter("\\D+");var b=new java.util.Scanner(p?x[1]:x[1].replace(" ","")).useDelimiter("\\D+");long r=1;while(a.hasNextLong()){long t=a.nextLong(),d=b.nextLong(),n=(long)Math.ceil((t-Math.sqrt(t*t-4.0*d))/2);r*=t-2*n+1;}return r+"";}}
